1	import { useMemo, useState } from 'react';
2	import {
3	  BarChart,
4	  Bar,
5	  XAxis,
6	  YAxis,
7	  CartesianGrid,
8	  Tooltip,
9	  ResponsiveContainer,
10	  PieChart,
11	  Pie,
12	  Cell,
13	  AreaChart,
14	  Area,
15	} from 'recharts';
16	import {
17	  TrendingUp,
18	  Package,
19	  Store,
20	  Download,
21	  Wallet,
22	  AlertCircle,
23	  User,
24	  Tag,
25	  FileText,
26	} from 'lucide-react';
27	import {
28	  format,
29	  parseISO,
30	  isValid,
31	  differenceInDays,
32	} from 'date-fns';
33	import { ptBR } from 'date-fns/locale';
34	import { Button } from '@/shared/ui/button';
35	import { cn } from '@/shared/lib/utils';
36	import * as XLSX from 'xlsx';
37	import { toast } from 'sonner';
38	import {
39	  Dialog,
40	  DialogContent,
41	  DialogDescription,
42	  DialogHeader,
43	  DialogTitle,
44	} from '@/shared/ui/dialog';
45	import {
46	  CATEGORIAS_NF,
47	  normalizeCategoria,
48	  type CategoriaNF,
49	} from '@/features/notas-fiscais/lib/categorias';
50	
51	// Colors (matching Momma Palette)
52	const KPICOLORS = {
53	  red: 'from-[#ef4444] to-[#b91c1c] text-white',
54	  orange: 'from-[#f97316] to-[#c2410c] text-white',
55	  gold: 'from-[#C5A065] to-[#B08D55] text-white',
56	  green: 'from-[#57715B] to-[#4A614E] text-white',
57	  dark: 'from-[#2D362E] to-[#1A1A1A] text-[#E6DCCF]',
58	  blue: 'from-[#3b82f6] to-[#1d4ed8] text-white',
59	  purple: 'from-[#8b5cf6] to-[#6d28d9] text-white',
60	  teal: 'from-[#0d9488] to-[#0f766e] text-white',
61	};
62	
63	const CHART_COLORS = [
64	  '#C5A065',
65	  '#57715B',
66	  '#8B4513',
67	  '#2D362E',
68	  '#ef4444',
69	  '#3b82f6',
70	  '#8b5cf6',
71	];
72	
73	interface InvoiceItem {
74	  id: number;
75	  numero_nota: string;
76	  fornecedor: string;
77	  data_nota: string | null;
78	  created_at: string;
79	  valor_total: number;
80	  status: string;
81	  itens_nota_fiscal?: {
82	    id: number;
83	    nome_produto: string;
84	    quantidade: number;
85	    valor_unitario: number;
86	    subtotal: number;
87	    categoria?: string;
88	  }[];
89	}
90	
91	interface InvoiceAnalyticsDashboardProps {
92	  invoices: InvoiceItem[];
93	  dateStart?: string; // YYYY-MM-DD
94	  dateEnd?: string;   // YYYY-MM-DD
95	}
96	
97	export function InvoiceAnalyticsDashboard({
98	  invoices,
99	  dateStart,
100	  dateEnd,
101	}: InvoiceAnalyticsDashboardProps) {
102	  const [selectedMetric, setSelectedMetric] = useState<string | null>(null);
103	  const [drilldownCategory, setDrilldownCategory] = useState<CategoriaNF | null>(null);
104	
105	  // --- daysDiff derived from props ---
106	  const daysDiff = useMemo(() => {
107	    if (dateStart && dateEnd) {
108	      const s = parseISO(dateStart);
109	      const e = parseISO(dateEnd);
110	      if (isValid(s) && isValid(e)) return Math.max(1, differenceInDays(e, s) + 1);
111	    }
112	    return 30;
113	  }, [dateStart, dateEnd]);
114	
115	  // --- Analytics Logic ---
116	  const analytics = useMemo(() => {
117	    const totalRecords = invoices.length;
118	    const totalValue = invoices.reduce(
119	      (acc, curr) => acc + (Number(curr.valor_total) || 0),
120	      0,
121	    );
122	
123	    const avgDailyVal = totalValue / daysDiff;
124	    const avgTicket = totalRecords > 0 ? totalValue / totalRecords : 0;
125	
126	    // Grouping Logic
127	    const isDailyGroup = daysDiff < 60;
128	
129	    const bySupplierValue: Record<string, number> = {};
130	    const supplierDisplayNames: Record<string, string> = {};
131	    const byCategoryValue: Record<string, number> = {};
132	    const byProductValue: Record<string, number> = {};
133	    const byCategoryProducts: Record<string, Record<string, { qtd: number; valor: number; fornecedores: Set<string> }>> = {};
134	    const byTime: Record<
135	      string,
136	      { date: string; value: number; count: number }
137	    > = {};
138	
139	    // Flatten items for product/category analysis
140	    let totalItems = 0;
141	
142	    invoices.forEach((invoice) => {
143	      const dateStr = invoice.data_nota || invoice.created_at;
144	      const date = dateStr ? parseISO(dateStr) : new Date();
145	      const timeKey = isDailyGroup
146	        ? format(date, 'yyyy-MM-dd')
147	        : format(date, 'yyyy-MM');
148	
149	      const val = Number(invoice.valor_total) || 0;
150	      const supplierRaw = (invoice.fornecedor || 'Outros').trim();
151	      const supplierKey = supplierRaw.toLowerCase();
152	
153	      // Time grouping
154	      if (!byTime[timeKey])
155	        byTime[timeKey] = { date: timeKey, value: 0, count: 0 };
156	      byTime[timeKey].value += val;
157	      byTime[timeKey].count += 1;
158	
159	      // Supplier grouping (case-insensitive)
160	      if (!bySupplierValue[supplierKey]) bySupplierValue[supplierKey] = 0;
161	      bySupplierValue[supplierKey] += val;
162	      // Guardar nome display (primeira ocorrência)
163	      if (!supplierDisplayNames[supplierKey]) supplierDisplayNames[supplierKey] = supplierRaw;
164	
165	      // Items grouping
166	      if (invoice.itens_nota_fiscal && invoice.itens_nota_fiscal.length > 0) {
167	        invoice.itens_nota_fiscal.forEach((item) => {
168	          totalItems++;
169	          const itemVal = Number(item.subtotal) || 0;
170	          const prod = item.nome_produto || 'Produto Desconhecido';
171	          const cat = normalizeCategoria(item.categoria);
172	
173	          byProductValue[prod] = (byProductValue[prod] || 0) + itemVal;
174	          byCategoryValue[cat] = (byCategoryValue[cat] || 0) + itemVal;
175	
176	          if (!byCategoryProducts[cat]) byCategoryProducts[cat] = {};
177	          if (!byCategoryProducts[cat][prod]) {
178	            byCategoryProducts[cat][prod] = { qtd: 0, valor: 0, fornecedores: new Set() };
179	          }
180	          byCategoryProducts[cat][prod].qtd += Number(item.quantidade) || 0;
181	          byCategoryProducts[cat][prod].valor += itemVal;
182	          if (invoice.fornecedor) {
183	            byCategoryProducts[cat][prod].fornecedores.add(invoice.fornecedor);
184	          }
185	        });
186	      } else {
187	        // If no items, attribute entire value to "Geral" or similar if needed,
188	        // but let's just track supplier/time for the main invoice.
189	      }
190	    });
191	
192	    // Computed Stats
193	    const topSupplierEntry = Object.entries(bySupplierValue)
194	      .map(([key, val]) => [supplierDisplayNames[key] || key, val] as [string, number])
195	      .sort((a, b) => b[1] - a[1])[0];
196	    const topCategoryEntry = Object.entries(byCategoryValue).sort(
197	      (a, b) => b[1] - a[1],
198	    )[0];
199	    const topProductEntry = Object.entries(byProductValue).sort(
200	      (a, b) => b[1] - a[1],
201	    )[0];
202	
203	    // Chart Data
204	    const formatDecimal = (num: number) => Number(num.toFixed(2));
205	
206	    const supplierChartData = Object.entries(bySupplierValue)
207	      .map(([key, value]) => ({ name: supplierDisplayNames[key] || key, value: formatDecimal(value) }))
208	      .sort((a, b) => b.value - a.value)
209	      .slice(0, 10);
210	
211	    const categoryChartData = Object.entries(byCategoryValue)
212	      .map(([name, value]) => ({ name, value: formatDecimal(value) }))
213	      .sort((a, b) => b.value - a.value);
214	
215	    const productChartData = Object.entries(byProductValue)
216	      .map(([name, value]) => ({ name, value: formatDecimal(value) }))
217	      .sort((a, b) => b.value - a.value)
218	      .slice(0, 10);
219	
220	    const timeData = Object.values(byTime)
221	      .sort((a, b) => a.date.localeCompare(b.date))
222	      .map((item) => ({
223	        ...item,
224	        value: formatDecimal(item.value),
225	        name: isDailyGroup
226	          ? format(parseISO(item.date), 'dd/MM')
227	          : format(parseISO(item.date), 'MMM/yy', { locale: ptBR }),
228	      }));
229	
230	    const detailedList = invoices
231	      .map((inv) => ({
232	        ...inv,
233	        val: Number(inv.valor_total) || 0,
234	        date: inv.data_nota || inv.created_at,
235	      }))
236	      .sort((a, b) => b.val - a.val);
237	
238	    return {
239	      totalRecords,
240	      totalValue: formatDecimal(totalValue),
241	      avgDailyVal: formatDecimal(avgDailyVal),
242	      avgTicket: formatDecimal(avgTicket),
243	      totalItems,
244	
245	      topSupplierName: topSupplierEntry ? topSupplierEntry[0] : '-',
246	      topSupplierAmount: topSupplierEntry
247	        ? formatDecimal(topSupplierEntry[1])
248	        : 0,
249	
250	      topCategoryName: topCategoryEntry ? topCategoryEntry[0] : '-',
251	      topCategoryAmount: topCategoryEntry
252	        ? formatDecimal(topCategoryEntry[1])
253	        : 0,
254	
255	      topProductName: topProductEntry ? topProductEntry[0] : '-',
256	      topProductAmount: topProductEntry ? formatDecimal(topProductEntry[1]) : 0,
257	
258	      supplierChartData,
259	      categoryChartData,
260	      productChartData,
261	      timeData,
262	      detailedList,
263	      byCategoryProducts,
264	    };
265	  }, [invoices, daysDiff]);
266	
267	  const drilldownSummary = useMemo(() => {
268	    if (!drilldownCategory) return { top: [], totalProdutos: 0, totalValor: 0 };
269	    const map = analytics.byCategoryProducts[drilldownCategory] || {};
270	    const all = Object.entries(map)
271	      .map(([nome_produto, d]) => ({
272	        nome_produto,
273	        qtd: d.qtd,
274	        valor: Number(d.valor.toFixed(2)),
275	        fornecedores: Array.from(d.fornecedores).join(', '),
276	      }))
277	      .sort((a, b) => b.valor - a.valor);
278	    return {
279	      top: all.slice(0, 10),
280	      totalProdutos: all.length,
281	      totalValor: all.reduce((acc, p) => acc + p.valor, 0),
282	    };
283	  }, [drilldownCategory, analytics.byCategoryProducts]);
284	
285	  // --- Export Logic ---
286	  const handleExport = () => {
287	    if (!analytics.detailedList.length) {
288	      toast.error('Sem dados para exportar.');
289	      return;
290	    }
291	
292	    const header = [
293	      'Data Emissão',
294	      'Fornecedor',
295	      'Número Nota',
296	      'Valor Total (R$)',
297	      'Status',
298	    ];
299	    const rows = analytics.detailedList.map((item) => [
300	      item.date ? format(parseISO(item.date), 'dd/MM/yyyy') : '-',
301	      item.fornecedor,
302	      item.numero_nota,
303	      item.val.toFixed(2),
304	      item.status,
305	    ]);
306	
307	    const wb = XLSX.utils.book_new();
308	    const ws = XLSX.utils.aoa_to_sheet([header, ...rows]);
309	    XLSX.utils.book_append_sheet(wb, ws, 'Notas Filtradas');
310	    XLSX.writeFile(
311	      wb,
312	      `Relatorio_Analise_Notas_${format(new Date(), 'yyyyMMdd_HHmm')}.xlsx`,
313	    );
314	    toast.success('Relatório gerado com sucesso!');
315	  };
316	
317	  // --- Modal/Detail Content for Clicked KPI ---
318	  const renderDetailContent = () => {
319	    if (!analytics || !selectedMetric) return null;
320	
321	    switch (selectedMetric) {
322	      case 'Total Gasto':
323	      case 'Evolução':
324	        return (
325	          <div className="h-80">
326	            <h4 className="text-sm font-bold text-center mb-4 text-muted-foreground">
327	              Evolução do Gasto
328	            </h4>
329	            <ResponsiveContainer width="100%" height="100%">
330	              <AreaChart data={analytics.timeData}>
331	                <defs>
332	                  <linearGradient id="colorVal" x1="0" y1="0" x2="0" y2="1">
333	                    <stop offset="5%" stopColor="#C5A065" stopOpacity={0.8} />
334	                    <stop offset="95%" stopColor="#C5A065" stopOpacity={0} />
335	                  </linearGradient>
336	                </defs>
337	                <CartesianGrid strokeDasharray="3 3" vertical={false} />
338	                <XAxis dataKey="name" tick={{ fontSize: 10 }} />
339	                <YAxis tick={{ fontSize: 10 }} />
340	                <Tooltip
341	                  formatter={(value: number) =>
342	                    new Intl.NumberFormat('pt-BR', {
343	                      style: 'currency',
344	                      currency: 'BRL',
345	                    }).format(value)
346	                  }
347	                />
348	                <Area
349	                  type="monotone"
350	                  dataKey="value"
351	                  stroke="#C5A065"
352	                  fill="url(#colorVal)"
353	                  name="Valor (R$)"
354	                />
355	              </AreaChart>
356	            </ResponsiveContainer>
357	          </div>
358	        );
359	      case 'Top Fornecedor':
360	        return (
361	          <div className="h-80">
362	            <h4 className="text-sm font-bold text-center mb-4 text-muted-foreground">
363	              Top 10 Fornecedores (Valor)
364	            </h4>
365	            <ResponsiveContainer width="100%" height="100%">
366	              <BarChart data={analytics.supplierChartData} layout="vertical">
367	                <CartesianGrid
368	                  strokeDasharray="3 3"
369	                  horizontal={true}
370	                  vertical={false}
371	                />
372	                <XAxis type="number" hide />
373	                <YAxis
374	                  dataKey="name"
375	                  type="category"
376	                  width={150}
377	                  tickFormatter={(value) =>
378	                    value.length > 20 ? `${value.substring(0, 20)}...` : value
379	                  }
380	                  tick={{ fontSize: 11 }}
381	                />
382	                <Tooltip
383	                  formatter={(value: number) =>
384	                    new Intl.NumberFormat('pt-BR', {
385	                      style: 'currency',
386	                      currency: 'BRL',
387	                    }).format(value)
388	                  }
389	                />
390	                <Bar
391	                  dataKey="value"
392	                  fill="#57715B"
393	                  radius={[0, 4, 4, 0]}
394	                  barSize={24}
395	                  name="Total (R$)"
396	                />
397	              </BarChart>
398	            </ResponsiveContainer>
399	          </div>
400	        );
401	      case 'Top Categoria': {
402	        const totalCategoria = analytics.categoryChartData.reduce((acc, c) => acc + c.value, 0);
403	        return (
404	          <div>
405	            <h4 className="text-sm font-bold text-center mb-1 text-muted-foreground">
406	              Gastos por Categoria
407	            </h4>
408	            <p className="text-xs text-center text-muted-foreground mb-3">
409	              Clique em uma categoria na lista para ver os produtos.
410	            </p>
411	            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 items-center">
412	              <div className="h-72">
413	                <ResponsiveContainer width="100%" height="100%">
414	                  <PieChart>
415	                    <Pie
416	                      data={analytics.categoryChartData}
417	                      dataKey="value"
418	                      nameKey="name"
419	                      cx="50%"
420	                      cy="50%"
421	                      outerRadius={90}
422	                      onClick={(entry: any) => {
423	                        const name = entry?.name as string | undefined;
424	                        if (name && (CATEGORIAS_NF as readonly string[]).includes(name)) {
425	                          setDrilldownCategory(name as CategoriaNF);
426	                        }
427	                      }}
428	                      style={{ cursor: 'pointer' }}
429	                    >
430	                      {analytics.categoryChartData.map((_, index) => (
431	                        <Cell
432	                          key={`cell-${index}`}
433	                          fill={CHART_COLORS[index % CHART_COLORS.length]}
434	                        />
435	                      ))}
436	                    </Pie>
437	                    <Tooltip
438	                      formatter={(value: number) =>
439	                        new Intl.NumberFormat('pt-BR', {
440	                          style: 'currency',
441	                          currency: 'BRL',
442	                        }).format(value)
443	                      }
444	                    />
445	                  </PieChart>
446	                </ResponsiveContainer>
447	              </div>
448	
449	              <div className="space-y-1 max-h-72 overflow-y-auto pr-2">
450	                {analytics.categoryChartData.map((c, index) => {
451	                  const pct = totalCategoria > 0 ? (c.value / totalCategoria) * 100 : 0;
452	                  const color = CHART_COLORS[index % CHART_COLORS.length];
453	                  const isCanonica = (CATEGORIAS_NF as readonly string[]).includes(c.name);
454	                  return (
455	                    <button
456	                      key={c.name}
457	                      type="button"
458	                      onClick={() => {
459	                        if (isCanonica) setDrilldownCategory(c.name as CategoriaNF);
460	                      }}
461	                      disabled={!isCanonica}
462	                      className="w-full flex items-center gap-2 p-2 rounded-lg hover:bg-[#57715B]/10 transition-colors text-left group disabled:opacity-60 disabled:cursor-not-allowed"
463	                    >
464	                      <span
465	                        className="w-3 h-3 rounded-sm shrink-0"
466	                        style={{ backgroundColor: color }}
467	                      />
468	                      <div className="flex-1 min-w-0">
469	                        <div className="flex items-baseline justify-between gap-2">
470	                          <span className="text-sm font-medium text-[#2D362E] dark:text-[#E6DCCF] truncate group-hover:text-[#57715B]">
471	                            {c.name}
472	                          </span>
473	                          <span className="text-xs font-semibold tabular-nums text-[#57715B]">
474	                            {new Intl.NumberFormat('pt-BR', {
475	                              style: 'currency',
476	                              currency: 'BRL',
477	                              maximumFractionDigits: 0,
478	                            }).format(c.value)}
479	                          </span>
480	                        </div>
481	                        <div className="flex items-center gap-2">
482	                          <div className="flex-1 h-1 bg-[#57715B]/10 rounded-full overflow-hidden">
483	                            <div
484	                              className="h-full rounded-full"
485	                              style={{ width: `${pct}%`, backgroundColor: color }}
486	                            />
487	                          </div>
488	                          <span className="text-[10px] tabular-nums text-muted-foreground w-10 text-right">
489	                            {pct.toFixed(1)}%
490	                          </span>
491	                        </div>
492	                      </div>
493	                    </button>
494	                  );
495	                })}
496	                {analytics.categoryChartData.length === 0 && (
497	                  <p className="text-center text-sm text-muted-foreground py-6">
498	                    Nenhuma categoria no período.
499	                  </p>
500	                )}
501	              </div>
502	            </div>
503	          </div>
504	        );
505	      }
506	      case 'Top Produto':
507	        return (
508	          <div className="h-80">
509	            <h4 className="text-sm font-bold text-center mb-4 text-muted-foreground">
510	              Top 10 Produtos (Custo)
511	            </h4>
512	            <ResponsiveContainer width="100%" height="100%">
513	              <BarChart data={analytics.productChartData} layout="vertical">
514	                <CartesianGrid
515	                  strokeDasharray="3 3"
516	                  horizontal={true}
517	                  vertical={false}
518	                />
519	                <XAxis type="number" hide />
520	                <YAxis
521	                  dataKey="name"
522	                  type="category"
523	                  width={120}
524	                  tick={{ fontSize: 10 }}
525	                />
526	                <Tooltip
527	                  formatter={(value: number) =>
528	                    new Intl.NumberFormat('pt-BR', {
529	                      style: 'currency',
530	                      currency: 'BRL',
531	                    }).format(value)
532	                  }
533	                />
534	                <Bar
535	                  dataKey="value"
536	                  fill="#8B4513"
537	                  radius={[0, 4, 4, 0]}
538	                  barSize={24}
539	                  name="Custo (R$)"
540	                />
541	              </BarChart>
542	            </ResponsiveContainer>
543	          </div>
544	        );
545	      case 'Ticket Médio':
546	        return (
547	          <div className="flex flex-col items-center justify-center h-64 text-center p-4">
548	            <Wallet className="w-16 h-16 text-[#C5A065] mb-4 opacity-50" />
549	            <h3 className="text-2xl font-bold text-[#2D362E]">Ticket Médio</h3>
550	            <p className="text-4xl font-extrabold text-[#C5A065] my-2">
551	              {new Intl.NumberFormat('pt-BR', {
552	                style: 'currency',
553	                currency: 'BRL',
554	              }).format(analytics.avgTicket)}
555	            </p>
556	            <p className="text-sm text-muted-foreground">
557	              Média do valor por nota fiscal processada no período.
558	            </p>
559	          </div>
560	        );
561	      default:
562	        return (
563	          <div className="p-4 text-center">
564	            Selecione uma métrica para ver detalhes.
565	          </div>
566	        );
567	    }
568	  };
569	
570	  return (
571	    <div className="space-y-6 pb-20 animate-in fade-in duration-500">
572	      {/* Analytics Header */}
573	      <div className="flex items-center justify-between bg-white/50 dark:bg-black/20 p-3 rounded-2xl backdrop-blur-sm border border-[#57715B]/10">
574	        <span className="text-sm font-semibold text-[#57715B] pl-1">Analytics Avançado</span>
575	        <Button
576	          data-mia-action="export"
577	          data-mia-expects-toast="export"
578	          onClick={handleExport}
579	          variant="ghost"
580	          size="icon"
581	          className="text-[#57715B] hover:bg-[#57715B]/10 rounded-xl h-10 w-10"
582	          title="Exportar Relatório"
583	        >
584	          <Download className="w-5 h-5" />
585	        </Button>
586	      </div>
587	
588	      {/* KPI Grid */}
589	      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4">
590	        <KPICard
591	          title="Total Gasto"
592	          value={new Intl.NumberFormat('pt-BR', {
593	            style: 'currency',
594	            currency: 'BRL',
595	          }).format(analytics.totalValue)}
596	          icon={Wallet}
597	          colorClass={KPICOLORS.gold}
598	          subtext="Neste período"
599	          onClick={() => setSelectedMetric('Total Gasto')}
600	        />
601	        <KPICard
602	          title="Top Fornecedor"
603	          value={analytics.topSupplierName}
604	          icon={Store}
605	          colorClass={KPICOLORS.green}
606	          subtext={`R$ ${analytics.topSupplierAmount.toFixed(0)}`}
607	          onClick={() => setSelectedMetric('Top Fornecedor')}
608	        />
