import { useMemo, useState } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  AreaChart,
  Area,
} from 'recharts';
import {
  TrendingUp,
  Package,
  Store,
  Download,
  Wallet,
  AlertCircle,
  User,
  Tag,
  FileText,
} from 'lucide-react';
import {
  format,
  parseISO,
  isValid,
  differenceInDays,
} from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { Button } from '@/shared/ui/button';
import { cn } from '@/shared/lib/utils';
import * as XLSX from 'xlsx';
import { toast } from 'sonner';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/shared/ui/dialog';
import {
  CATEGORIAS_NF,
  normalizeCategoria,
  type CategoriaNF,
} from '@/features/notas-fiscais/lib/categorias';

// Colors (matching Momma Palette)
const KPICOLORS = {
  red: 'from-[#ef4444] to-[#b91c1c] text-white',
  orange: 'from-[#f97316] to-[#c2410c] text-white',
  gold: 'from-[#C5A065] to-[#B08D55] text-white',
  green: 'from-[#57715B] to-[#4A614E] text-white',
  dark: 'from-[#2D362E] to-[#1A1A1A] text-[#E6DCCF]',
  blue: 'from-[#3b82f6] to-[#1d4ed8] text-white',
  purple: 'from-[#8b5cf6] to-[#6d28d9] text-white',
  teal: 'from-[#0d9488] to-[#0f766e] text-white',
};

const CHART_COLORS = [
  '#C5A065',
  '#57715B',
  '#8B4513',
  '#2D362E',
  '#ef4444',
  '#3b82f6',
  '#8b5cf6',
];

interface InvoiceItem {
  id: number;
  numero_nota: string;
  fornecedor: string;
  data_nota: string | null;
  created_at: string;
  valor_total: number;
  status: string;
  itens_nota_fiscal?: {
    id: number;
    nome_produto: string;
    quantidade: number;
    valor_unitario: number;
    subtotal: number;
    categoria?: string;
  }[];
}

interface InvoiceAnalyticsDashboardProps {
  invoices: InvoiceItem[];
  dateStart?: string; // YYYY-MM-DD
  dateEnd?: string;   // YYYY-MM-DD
}

export function InvoiceAnalyticsDashboard({
  invoices,
  dateStart,
  dateEnd,
}: InvoiceAnalyticsDashboardProps) {
  const [selectedMetric, setSelectedMetric] = useState<string | null>(null);
  const [drilldownCategory, setDrilldownCategory] = useState<CategoriaNF | null>(null);

  // --- daysDiff derived from props ---
  const daysDiff = useMemo(() => {
    if (dateStart && dateEnd) {
      const s = parseISO(dateStart);
      const e = parseISO(dateEnd);
      if (isValid(s) && isValid(e)) return Math.max(1, differenceInDays(e, s) + 1);
    }
    return 30;
  }, [dateStart, dateEnd]);

  // --- Analytics Logic ---
  const analytics = useMemo(() => {
    const totalRecords = invoices.length;
    const totalValue = invoices.reduce(
      (acc, curr) => acc + (Number(curr.valor_total) || 0),
      0,
    );

    const avgDailyVal = totalValue / daysDiff;
    const avgTicket = totalRecords > 0 ? totalValue / totalRecords : 0;

    // Grouping Logic
    const isDailyGroup = daysDiff < 60;

    const bySupplierValue: Record<string, number> = {};
    const supplierDisplayNames: Record<string, string> = {};
    const byCategoryValue: Record<string, number> = {};
    const byProductValue: Record<string, number> = {};
    const byCategoryProducts: Record<string, Record<string, { qtd: number; valor: number; fornecedores: Set<string> }>> = {};
    const byTime: Record<
      string,
      { date: string; value: number; count: number }
    > = {};

    // Flatten items for product/category analysis
    let totalItems = 0;

    invoices.forEach((invoice) => {
      const dateStr = invoice.data_nota || invoice.created_at;
      const date = dateStr ? parseISO(dateStr) : new Date();
      const timeKey = isDailyGroup
        ? format(date, 'yyyy-MM-dd')
        : format(date, 'yyyy-MM');

      const val = Number(invoice.valor_total) || 0;
      const supplierRaw = (invoice.fornecedor || 'Outros').trim();
      const supplierKey = supplierRaw.toLowerCase();

      // Time grouping
      if (!byTime[timeKey])
        byTime[timeKey] = { date: timeKey, value: 0, count: 0 };
      byTime[timeKey].value += val;
      byTime[timeKey].count += 1;

      // Supplier grouping (case-insensitive)
      if (!bySupplierValue[supplierKey]) bySupplierValue[supplierKey] = 0;
      bySupplierValue[supplierKey] += val;
      // Guardar nome display (primeira ocorrência)
      if (!supplierDisplayNames[supplierKey]) supplierDisplayNames[supplierKey] = supplierRaw;

      // Items grouping
      if (invoice.itens_nota_fiscal && invoice.itens_nota_fiscal.length > 0) {
        invoice.itens_nota_fiscal.forEach((item) => {
          totalItems++;
          const itemVal = Number(item.subtotal) || 0;
          const prod = item.nome_produto || 'Produto Desconhecido';
          const cat = normalizeCategoria(item.categoria);

          byProductValue[prod] = (byProductValue[prod] || 0) + itemVal;
          byCategoryValue[cat] = (byCategoryValue[cat] || 0) + itemVal;

          if (!byCategoryProducts[cat]) byCategoryProducts[cat] = {};
          if (!byCategoryProducts[cat][prod]) {
            byCategoryProducts[cat][prod] = { qtd: 0, valor: 0, fornecedores: new Set() };
          }
          byCategoryProducts[cat][prod].qtd += Number(item.quantidade) || 0;
          byCategoryProducts[cat][prod].valor += itemVal;
          if (invoice.fornecedor) {
            byCategoryProducts[cat][prod].fornecedores.add(invoice.fornecedor);
          }
        });
      } else {
        // If no items, attribute entire value to "Geral" or similar if needed,
        // but let's just track supplier/time for the main invoice.
      }
    });

    // Computed Stats
    const topSupplierEntry = Object.entries(bySupplierValue)
      .map(([key, val]) => [supplierDisplayNames[key] || key, val] as [string, number])
      .sort((a, b) => b[1] - a[1])[0];
    const topCategoryEntry = Object.entries(byCategoryValue).sort(
      (a, b) => b[1] - a[1],
    )[0];
    const topProductEntry = Object.entries(byProductValue).sort(
      (a, b) => b[1] - a[1],
    )[0];

    // Chart Data
    const formatDecimal = (num: number) => Number(num.toFixed(2));

    const supplierChartData = Object.entries(bySupplierValue)
      .map(([key, value]) => ({ name: supplierDisplayNames[key] || key, value: formatDecimal(value) }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 10);

    const categoryChartData = Object.entries(byCategoryValue)
      .map(([name, value]) => ({ name, value: formatDecimal(value) }))
      .sort((a, b) => b.value - a.value);

    const productChartData = Object.entries(byProductValue)
      .map(([name, value]) => ({ name, value: formatDecimal(value) }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 10);

    const timeData = Object.values(byTime)
      .sort((a, b) => a.date.localeCompare(b.date))
      .map((item) => ({
        ...item,
        value: formatDecimal(item.value),
        name: isDailyGroup
          ? format(parseISO(item.date), 'dd/MM')
          : format(parseISO(item.date), 'MMM/yy', { locale: ptBR }),
      }));

    const detailedList = invoices
      .map((inv) => ({
        ...inv,
        val: Number(inv.valor_total) || 0,
        date: inv.data_nota || inv.created_at,
      }))
      .sort((a, b) => b.val - a.val);

    return {
      totalRecords,
      totalValue: formatDecimal(totalValue),
      avgDailyVal: formatDecimal(avgDailyVal),
      avgTicket: formatDecimal(avgTicket),
      totalItems,

      topSupplierName: topSupplierEntry ? topSupplierEntry[0] : '-',
      topSupplierAmount: topSupplierEntry
        ? formatDecimal(topSupplierEntry[1])
        : 0,

      topCategoryName: topCategoryEntry ? topCategoryEntry[0] : '-',
      topCategoryAmount: topCategoryEntry
        ? formatDecimal(topCategoryEntry[1])
        : 0,

      topProductName: topProductEntry ? topProductEntry[0] : '-',
      topProductAmount: topProductEntry ? formatDecimal(topProductEntry[1]) : 0,

      supplierChartData,
      categoryChartData,
      productChartData,
      timeData,
      detailedList,
      byCategoryProducts,
    };
  }, [invoices, daysDiff]);

  const drilldownSummary = useMemo(() => {
    if (!drilldownCategory) return { top: [], totalProdutos: 0, totalValor: 0 };
    const map = analytics.byCategoryProducts[drilldownCategory] || {};
    const all = Object.entries(map)
      .map(([nome_produto, d]) => ({
        nome_produto,
        qtd: d.qtd,
        valor: Number(d.valor.toFixed(2)),
        fornecedores: Array.from(d.fornecedores).join(', '),
      }))
      .sort((a, b) => b.valor - a.valor);
    return {
      top: all.slice(0, 10),
      totalProdutos: all.length,
      totalValor: all.reduce((acc, p) => acc + p.valor, 0),
    };
  }, [drilldownCategory, analytics.byCategoryProducts]);

  // --- Export Logic ---
  const handleExport = () => {
    if (!analytics.detailedList.length) {
      toast.error('Sem dados para exportar.');
      return;
    }

    const header = [
      'Data Emissão',
      'Fornecedor',
      'Número Nota',
      'Valor Total (R$)',
      'Status',
    ];
    const rows = analytics.detailedList.map((item) => [
      item.date ? format(parseISO(item.date), 'dd/MM/yyyy') : '-',
      item.fornecedor,
      item.numero_nota,
      item.val.toFixed(2),
      item.status,
    ]);

    const wb = XLSX.utils.book_new();
    const ws = XLSX.utils.aoa_to_sheet([header, ...rows]);
    XLSX.utils.book_append_sheet(wb, ws, 'Notas Filtradas');
    XLSX.writeFile(
      wb,
      `Relatorio_Analise_Notas_${format(new Date(), 'yyyyMMdd_HHmm')}.xlsx`,
    );
    toast.success('Relatório gerado com sucesso!');
  };

  // --- Modal/Detail Content for Clicked KPI ---
  const renderDetailContent = () => {
    if (!analytics || !selectedMetric) return null;

    switch (selectedMetric) {
      case 'Total Gasto':
      case 'Evolução':
        return (
          <div className="h-80">
            <h4 className="text-sm font-bold text-center mb-4 text-muted-foreground">
              Evolução do Gasto
            </h4>
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={analytics.timeData}>
                <defs>
                  <linearGradient id="colorVal" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#C5A065" stopOpacity={0.8} />
                    <stop offset="95%" stopColor="#C5A065" stopOpacity={0} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" tick={{ fontSize: 10 }} />
                <YAxis tick={{ fontSize: 10 }} />
                <Tooltip
                  formatter={(value: number) =>
                    new Intl.NumberFormat('pt-BR', {
                      style: 'currency',
                      currency: 'BRL',
                    }).format(value)
                  }
                />
                <Area
                  type="monotone"
                  dataKey="value"
                  stroke="#C5A065"
                  fill="url(#colorVal)"
                  name="Valor (R$)"
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        );
      case 'Top Fornecedor':
        return (
          <div className="h-80">
            <h4 className="text-sm font-bold text-center mb-4 text-muted-foreground">
              Top 10 Fornecedores (Valor)
            </h4>
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={analytics.supplierChartData} layout="vertical">
                <CartesianGrid
                  strokeDasharray="3 3"
                  horizontal={true}
                  vertical={false}
                />
                <XAxis type="number" hide />
                <YAxis
                  dataKey="name"
                  type="category"
                  width={150}
                  tickFormatter={(value) =>
                    value.length > 20 ? `${value.substring(0, 20)}...` : value
                  }
                  tick={{ fontSize: 11 }}
                />
                <Tooltip
                  formatter={(value: number) =>
                    new Intl.NumberFormat('pt-BR', {
                      style: 'currency',
                      currency: 'BRL',
                    }).format(value)
                  }
                />
                <Bar
                  dataKey="value"
                  fill="#57715B"
                  radius={[0, 4, 4, 0]}
                  barSize={24}
                  name="Total (R$)"
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        );
      case 'Top Categoria': {
        const totalCategoria = analytics.categoryChartData.reduce((acc, c) => acc + c.value, 0);
        return (
          <div>
            <h4 className="text-sm font-bold text-center mb-1 text-muted-foreground">
              Gastos por Categoria
            </h4>
            <p className="text-xs text-center text-muted-foreground mb-3">
              Clique em uma categoria na lista para ver os produtos.
            </p>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 items-center">
              <div className="h-72">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={analytics.categoryChartData}
                      dataKey="value"
                      nameKey="name"
                      cx="50%"
                      cy="50%"
                      outerRadius={90}
                      onClick={(entry: any) => {
                        const name = entry?.name as string | undefined;
                        if (name && (CATEGORIAS_NF as readonly string[]).includes(name)) {
                          setDrilldownCategory(name as CategoriaNF);
                        }
                      }}
                      style={{ cursor: 'pointer' }}
                    >
                      {analytics.categoryChartData.map((_, index) => (
                        <Cell
                          key={`cell-${index}`}
                          fill={CHART_COLORS[index % CHART_COLORS.length]}
                        />
                      ))}
                    </Pie>
                    <Tooltip
                      formatter={(value: number) =>
                        new Intl.NumberFormat('pt-BR', {
                          style: 'currency',
                          currency: 'BRL',
                        }).format(value)
                      }
                    />
                  </PieChart>
                </ResponsiveContainer>
              </div>

              <div className="space-y-1 max-h-72 overflow-y-auto pr-2">
                {analytics.categoryChartData.map((c, index) => {
                  const pct = totalCategoria > 0 ? (c.value / totalCategoria) * 100 : 0;
                  const color = CHART_COLORS[index % CHART_COLORS.length];
                  const isCanonica = (CATEGORIAS_NF as readonly string[]).includes(c.name);
                  return (
                    <button
                      key={c.name}
                      type="button"
                      onClick={() => {
                        if (isCanonica) setDrilldownCategory(c.name as CategoriaNF);
                      }}
                      disabled={!isCanonica}
                      className="w-full flex items-center gap-2 p-2 rounded-lg hover:bg-[#57715B]/10 transition-colors text-left group disabled:opacity-60 disabled:cursor-not-allowed"
                    >
                      <span
                        className="w-3 h-3 rounded-sm shrink-0"
                        style={{ backgroundColor: color }}
                      />
                      <div className="flex-1 min-w-0">
                        <div className="flex items-baseline justify-between gap-2">
                          <span className="text-sm font-medium text-[#2D362E] dark:text-[#E6DCCF] truncate group-hover:text-[#57715B]">
                            {c.name}
                          </span>
                          <span className="text-xs font-semibold tabular-nums text-[#57715B]">
                            {new Intl.NumberFormat('pt-BR', {
                              style: 'currency',
                              currency: 'BRL',
                              maximumFractionDigits: 0,
                            }).format(c.value)}
                          </span>
                        </div>
                        <div className="flex items-center gap-2">
                          <div className="flex-1 h-1 bg-[#57715B]/10 rounded-full overflow-hidden">
                            <div
