  return (
    <div className="space-y-6 pb-20 animate-in fade-in duration-500">
      {/* Analytics Header */}
      <div className="flex items-center justify-between bg-white/50 dark:bg-black/20 p-3 rounded-2xl backdrop-blur-sm border border-[#57715B]/10">
