        <KPICard
          title="Quantidade Notas"
          value={String(analytics.totalRecords)}
          icon={FileText}
          colorClass={KPICOLORS.blue}
          subtext={`${analytics.totalItems} itens`}
          onClick={() => {}}
        />
      </div>

      {/* Secondary KPI Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <KPICard
          title="Ticket Médio"
          value={new Intl.NumberFormat('pt-BR', {
            style: 'currency',
            currency: 'BRL',
          }).format(analytics.avgTicket)}
          icon={TrendingUp}
          colorClass={KPICOLORS.teal}
          subtext="Por nota"
          onClick={() => setSelectedMetric('Ticket Médio')}
        />
        <KPICard
          title="Top Produto (Custo)"
          value={analytics.topProductName}
