        <div className="bg-white/50 dark:bg-black/20 p-6 rounded-2xl border border-[#57715B]/10 animate-in fade-in slide-in-from-top-4">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-bold text-[#2D362E] dark:text-[#E6DCCF]">
              {selectedMetric}
            </h3>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setSelectedMetric(null)}
              className="h-8 w-8 p-0 rounded-full"
            >
              x
            </Button>
          </div>
          {renderDetailContent()}
        </div>
      )}

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <ChartCard title="Evolução de Gastos (R$)">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={analytics.timeData}>
              <defs>
                <linearGradient id="colorValMain" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#57715B" stopOpacity={0.8} />
                  <stop offset="95%" stopColor="#57715B" stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid
                strokeDasharray="3 3"
                vertical={false}
                stroke="rgba(0,0,0,0.05)"
              />
              <XAxis
                dataKey="name"
                axisLine={false}
                tickLine={false}
                tick={{ fill: '#57715B', fontSize: 10 }}
              />
              <YAxis
                axisLine={false}
                tickLine={false}
                tick={{ fill: '#57715B', fontSize: 10 }}
              />
              <Tooltip
                contentStyle={{
                  borderRadius: '12px',
                  border: 'none',
                  boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                }}
                formatter={(value: number) =>
                  new Intl.NumberFormat('pt-BR', {
                    style: 'currency',
                    currency: 'BRL',
                  }).format(value)
                }
              />
              <Area
                type="monotone"
                dataKey="value"
                stroke="#57715B"
                fillOpacity={1}
                fill="url(#colorValMain)"
              />
            </AreaChart>
          </ResponsiveContainer>
        </ChartCard>

        <Dialog open={!!drilldownCategory} onOpenChange={(o) => !o && setDrilldownCategory(null)}>
          <DialogContent data-mia-modal="top-10-drilldown-category" className="max-w-3xl max-h-[85vh] overflow-hidden flex flex-col">
            <DialogHeader>
              <DialogTitle className="text-[#2D362E]">
