              </DialogTitle>
              <DialogDescription>
                {drilldownSummary.totalProdutos} produtos distintos · Total{' '}
                {new Intl.NumberFormat('pt-BR', {
                  style: 'currency',
                  currency: 'BRL',
                }).format(drilldownSummary.totalValor)}
                . Para ver todos os produtos e reclassificar em massa, use{' '}
                <b>Relatórios → Categorias</b>.
              </DialogDescription>
            </DialogHeader>
            <div className="overflow-y-auto pr-2 flex-1">
              <table className="w-full text-sm">
                <thead className="sticky top-0 bg-white dark:bg-[#1A1A1A] border-b border-[#57715B]/10">
                  <tr className="text-left text-xs text-muted-foreground">
                    <th className="py-2 px-2">#</th>
                    <th className="py-2 px-2">Produto</th>
                    <th className="py-2 px-2 text-right">Qtd</th>
                    <th className="py-2 px-2 text-right">Valor</th>
                  </tr>
                </thead>
                <tbody>
                  {drilldownSummary.top.map((p, i) => (
                    <tr key={p.nome_produto} className="border-b border-[#57715B]/5 hover:bg-[#57715B]/5">
                      <td className="py-2 px-2 text-muted-foreground tabular-nums">{i + 1}</td>
                      <td className="py-2 px-2">
                        <div className="font-medium text-[#2D362E] dark:text-[#E6DCCF]">
                          {p.nome_produto}
                        </div>
                        {p.fornecedores && (
                          <div className="text-[10px] text-muted-foreground truncate max-w-[280px]">
                            {p.fornecedores}
                          </div>
                        )}
                      </td>
                      <td className="py-2 px-2 text-right tabular-nums">{p.qtd.toFixed(2)}</td>
                      <td className="py-2 px-2 text-right tabular-nums font-semibold">
                        {new Intl.NumberFormat('pt-BR', {
                          style: 'currency',
