// Helpers
function KPICard({
  title,
  value,
  icon: Icon,
  colorClass,
  subtext,
  onClick,
}: any) {
  return (
    <div
      onClick={onClick}
      className={`p-4 rounded-2xl bg-white dark:bg-[#1A1A1A] border border-gray-100 dark:border-gray-800 shadow-sm cursor-pointer hover:scale-[1.02] transition-all relative overflow-hidden group`}
    >
      <div
        className={`absolute top-0 right-0 p-3 opacity-10 group-hover:opacity-20 transition-opacity`}
      >
        <Icon className="w-16 h-16" />
      </div>
      <div className="flex items-center gap-3 mb-2">
        <div
          className={`p-2 rounded-lg bg-gradient-to-br ${colorClass} shadow-md`}
        >
          <Icon className="w-5 h-5 text-white" />
        </div>
        <h3 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
          {title}
        </h3>
      </div>
      <div className="relative z-10">
        <div className="text-2xl font-bold text-[#2D362E] dark:text-[#E6DCCF] truncate">
          {value}
        </div>
        {subtext && (
          <div className="text-xs text-muted-foreground mt-1 font-medium">
            {subtext}
          </div>
        )}
      </div>
    </div>
  );
}

function ChartCard({
  title,
  children,
}: {
  title: string;
  children: React.ReactNode;
}) {
  return (
    <div className="bg-white/40 dark:bg-black/20 p-6 rounded-3xl border border-[#57715B]/10 backdrop-blur-sm h-80">
      <h3 className="text-sm font-bold text-[#2D362E] dark:text-[#E6DCCF] mb-6 flex items-center gap-2">
        {title}
      </h3>
      <div className="h-[calc(100%-2rem)]">{children}</div>
    </div>
  );
}

import { useMemo } from 'react';
import { GlassCard } from '@/shared/ui/glass-card';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
} from 'recharts';
import { useIsMobile } from '@/shared/hooks/use-mobile';
import { TrendingUp, DollarSign, FileText, Package } from 'lucide-react';

interface AnalyticsDashboardProps {
  notas: any[];
}

export function AnalyticsDashboard({ notas }: AnalyticsDashboardProps) {
  const isMobile = useIsMobile();

  const metrics = useMemo(() => {
    const totalNotas = notas.length;
    const totalValor = notas.reduce(
      (acc, curr) => acc + (parseFloat(curr.valor_total) || 0),
      0,
    );
    const averageValor = totalNotas > 0 ? totalValor / totalNotas : 0;

    // Group by Month (Last 6-12 months)
    const byMonthMap = new Map();
    notas.forEach((nota) => {
      const date = new Date(nota.data_nota || nota.created_at);
      const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
      const prev = byMonthMap.get(key) || 0;
      byMonthMap.set(key, prev + (parseFloat(nota.valor_total) || 0));
    });

    const byMonth = Array.from(byMonthMap.entries())
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => a.name.localeCompare(b.name));

    // Top Suppliers (case-insensitive — OCR gera variações de caixa)
    const bySupplierMap = new Map<string, { display: string; value: number }>();
    notas.forEach((nota) => {
      const raw = (nota.fornecedor || 'Desconhecido').trim();
      const key = raw.toLowerCase();
      const prev = bySupplierMap.get(key);
      if (prev) {
        prev.value += parseFloat(nota.valor_total) || 0;
      } else {
        bySupplierMap.set(key, { display: raw, value: parseFloat(nota.valor_total) || 0 });
      }
    });

    const topSuppliers = Array.from(bySupplierMap.values())
      .map(({ display, value }) => ({ name: display, value }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 5);

    // Top Products & Categories
    const byProductMap = new Map();
    const byCategoryMap = new Map();

    notas.forEach((nota) => {
      const itens = nota.itens_nota_fiscal || [];
      itens.forEach((item: any) => {
        const subtotal = parseFloat(item.subtotal || 0);

        // Product
        const prodName = item.nome_produto || 'Outros';
        byProductMap.set(
          prodName,
          (byProductMap.get(prodName) || 0) + subtotal,
        );

        // Category
        const catName = item.categoria || 'Sem Categoria';
        byCategoryMap.set(
          catName,
          (byCategoryMap.get(catName) || 0) + subtotal,
        );
      });
    });

    const topProducts = Array.from(byProductMap.entries())
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 5);

    const uniqueProductsCount = byProductMap.size;

    const byCategory = Array.from(byCategoryMap.entries())
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    return {
      totalNotas,
      totalValor,
      averageValor,
      byMonth,
      topSuppliers,
      topProducts,
      byCategory,
      uniqueProductsCount,
    };
  }, [notas]);

  const currencyFormatter = (value: number) =>
    new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
    }).format(value);

  // Momma Palette: Green #57715B, Gold #C5A065, and complementary shades
  const COLORS = [
    '#57715B',
    '#C5A065',
    '#8FA893',
    '#D4B886',
    '#3A4D3D',
    '#8F7348',
    '#2D362E',
  ];

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* Cards de Resumo */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <GlassCard
          variant="premium"
          className="p-6 flex items-center justify-between group hover:scale-[1.02] transition-transform duration-300"
        >
          <div>
            <p className="text-[10px] font-bold text-[#C5A065] uppercase tracking-wider">
              Total Gasto
            </p>
            <h3 className="text-2xl font-bold text-[#2D362E] dark:text-[#E6DCCF] mt-1">
              {currencyFormatter(metrics.totalValor)}
            </h3>
          </div>
          <div className="h-12 w-12 bg-[#C5A065]/10 rounded-2xl flex items-center justify-center group-hover:bg-[#C5A065]/20 transition-colors">
            <DollarSign className="h-6 w-6 text-[#C5A065]" />
          </div>
        </GlassCard>

        <GlassCard
          variant="premium"
          className="p-6 flex items-center justify-between group hover:scale-[1.02] transition-transform duration-300"
        >
          <div>
            <p className="text-[10px] font-bold text-[#57715B] uppercase tracking-wider">
              Notas Processadas
            </p>
            <h3 className="text-2xl font-bold text-[#2D362E] dark:text-[#E6DCCF] mt-1">
              {metrics.totalNotas}
            </h3>
          </div>
          <div className="h-12 w-12 bg-[#57715B]/10 rounded-2xl flex items-center justify-center group-hover:bg-[#57715B]/20 transition-colors">
            <FileText className="h-6 w-6 text-[#57715B]" />
          </div>
        </GlassCard>

        <GlassCard
          variant="premium"
          className="p-6 flex items-center justify-between group hover:scale-[1.02] transition-transform duration-300"
        >
          <div>
            <p className="text-[10px] font-bold text-[#C5A065] uppercase tracking-wider">
              Média por Nota
            </p>
            <h3 className="text-2xl font-bold text-[#2D362E] dark:text-[#E6DCCF] mt-1">
              {currencyFormatter(metrics.averageValor)}
            </h3>
          </div>
          <div className="h-12 w-12 bg-[#C5A065]/10 rounded-2xl flex items-center justify-center group-hover:bg-[#C5A065]/20 transition-colors">
            <TrendingUp className="h-6 w-6 text-[#C5A065]" />
          </div>
        </GlassCard>

        <GlassCard
          variant="premium"
          className="p-6 flex items-center justify-between group hover:scale-[1.02] transition-transform duration-300"
        >
          <div>
            <p className="text-[10px] font-bold text-[#57715B] uppercase tracking-wider">
              Produtos Únicos
            </p>
            <h3 className="text-2xl font-bold text-[#2D362E] dark:text-[#E6DCCF] mt-1">
              {metrics.uniqueProductsCount}
            </h3>
          </div>
          <div className="h-12 w-12 bg-[#57715B]/10 rounded-2xl flex items-center justify-center group-hover:bg-[#57715B]/20 transition-colors">
            <Package className="h-6 w-6 text-[#57715B]" />
          </div>
        </GlassCard>
      </div>

      {/* Gráficos */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Evolução Mensal */}
        <GlassCard variant="premium" className="col-span-1 p-6">
          <div className="mb-6">
            <h3 className="text-lg font-bold text-[#2D362E] dark:text-[#E6DCCF]">
              Evolução Mensal
            </h3>
            <p className="text-sm text-[#57715B]/80 font-medium">
              Gastos totais por mês de emissão
            </p>
          </div>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={metrics.byMonth}
                margin={{ top: 20, right: 30, left: 20, bottom: 5 }}
              >
                <CartesianGrid
                  strokeDasharray="3 3"
                  vertical={false}
                  stroke="#57715B"
                  opacity={0.1}
                />
                <XAxis
                  dataKey="name"
                  stroke="#57715B"
                  fontSize={12}
                  tickLine={false}
                  axisLine={false}
                  opacity={0.7}
                />
                <YAxis
                  stroke="#57715B"
                  fontSize={12}
                  tickLine={false}
                  axisLine={false}
                  tickFormatter={(value) => `R$ ${value / 1000}k`}
                  opacity={0.7}
                />
                <Tooltip
                  cursor={{ fill: '#57715B', opacity: 0.1 }}
                  contentStyle={{
                    borderRadius: '16px',
                    border: '1px solid rgba(255,255,255,0.5)',
                    background: 'rgba(255,255,255,0.9)',
                    backdropFilter: 'blur(12px)',
                    boxShadow: '0 8px 32px rgba(0,0,0,0.1)',
                    color: '#2D362E',
                  }}
                  formatter={(value: number) => [
                    currencyFormatter(value),
                    'Total',
                  ]}
                  labelStyle={{ color: '#57715B', fontWeight: 'bold' }}
                />
                <Bar
                  dataKey="value"
                  fill="#57715B"
                  radius={[6, 6, 0, 0]}
                  opacity={0.9}
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </GlassCard>

        {/* Top Fornecedores */}
        <GlassCard variant="premium" className="col-span-1 p-6">
          <div className="mb-6">
            <h3 className="text-lg font-bold text-[#2D362E] dark:text-[#E6DCCF]">
              Top Fornecedores
            </h3>
            <p className="text-sm text-[#57715B]/80 font-medium">
              Maiores gastos acumulados
            </p>
          </div>
          <div className="h-[300px]">
            {metrics.topSuppliers.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={metrics.topSuppliers}
                  layout="vertical"
                  margin={{ top: 5, right: 30, left: 20, bottom: 5 }}
                >
                  <CartesianGrid
                    strokeDasharray="3 3"
                    horizontal={true}
                    vertical={false}
                    stroke="#57715B"
                    opacity={0.1}
                  />
                  <XAxis type="number" hide />
                  <YAxis
                    dataKey="name"
                    type="category"
                    width={100}
                    tick={{ fill: '#57715B', fontSize: 11 }}
                    tickLine={false}
                    axisLine={false}
                  />
                  <Tooltip
                    contentStyle={{
                      borderRadius: '16px',
                      border: '1px solid rgba(255,255,255,0.5)',
                      background: 'rgba(255,255,255,0.9)',
                      backdropFilter: 'blur(12px)',
                      boxShadow: '0 8px 32px rgba(0,0,0,0.1)',
                      color: '#2D362E',
                    }}
                    formatter={(value: number) => [
                      currencyFormatter(value),
                      'Valor',
                    ]}
                    labelStyle={{ color: '#57715B', fontWeight: 'bold' }}
                  />
                  <Bar dataKey="value" radius={[0, 6, 6, 0]} opacity={0.9}>
                    {metrics.topSuppliers.map((entry, index) => (
                      <Cell
                        key={`cell-${index}`}
                        fill={COLORS[index % COLORS.length]}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full flex items-center justify-center text-[#57715B]/50 font-medium">
                Dados insuficientes
              </div>
            )}
          </div>
        </GlassCard>

        {/* Top Produtos / Categories Row */}
        <GlassCard variant="premium" className="col-span-1 md:col-span-2 p-6">
          <div className="mb-6 flex items-center justify-between">
            <div>
              <h3 className="text-lg font-bold text-[#2D362E] dark:text-[#E6DCCF]">
                Gastos por Categoria
              </h3>
              <p className="text-sm text-[#57715B]/80 font-medium">
                Distribuição de gastos nos itens
              </p>
            </div>
          </div>
          <div className="flex flex-col md:flex-row items-center justify-between h-[300px]">
            <div className="w-full md:w-1/2 h-full">
              {metrics.byCategory.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={metrics.byCategory}
                      cx="50%"
                      cy="50%"
                      labelLine={false}
                      label={false}
                      outerRadius={100}
                      fill="#57715B"
                      dataKey="value"
                      stroke="#fff"
                      strokeWidth={2}
                    >
                      {metrics.byCategory.map((entry, index) => (
                        <Cell
                          key={`cell-${index}`}
                          fill={COLORS[index % COLORS.length]}
                        />
                      ))}
                    </Pie>
                    <Tooltip
                      contentStyle={{
                        borderRadius: '16px',
                        border: '1px solid rgba(255,255,255,0.5)',
                        background: 'rgba(255,255,255,0.9)',
                        backdropFilter: 'blur(12px)',
                        boxShadow: '0 8px 32px rgba(0,0,0,0.1)',
                        color: '#2D362E',
                      }}
                      formatter={(value: number) => currencyFormatter(value)}
                      itemStyle={{ color: '#57715B' }}
                    />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex items-center justify-center text-[#57715B]/50 font-medium">
                  Sem dados de itens (categorias)
                </div>
              )}
            </div>

            {/* Custom Legend */}
            <div className="w-full md:w-1/2 h-full overflow-y-auto pr-2 custom-scrollbar">
              <div className="grid grid-cols-1 gap-3 py-4">
                {metrics.byCategory.map((entry, index) => {
                  const total = metrics.byCategory.reduce(
                    (acc, curr) => acc + curr.value,
                    0,
                  );
                  const percent = total > 0 ? (entry.value / total) * 100 : 0;

                  return (
                    <div
                      key={index}
                      className="flex items-center justify-between p-2 rounded-xl hover:bg-[#57715B]/5 transition-colors group"
                    >
                      <div className="flex items-center gap-3">
                        <div
                          className="w-3 h-3 rounded-full shadow-sm"
                          style={{
                            backgroundColor: COLORS[index % COLORS.length],
                          }}
                        />
                        <span className="text-sm font-medium text-[#2D362E] dark:text-[#E6DCCF] truncate max-w-[120px]">
                          {entry.name}
                        </span>
                      </div>
                      <div className="flex flex-col items-end">
                        <span className="text-sm font-bold text-[#57715B]">
                          {currencyFormatter(entry.value)}
                        </span>
                        <span className="text-[10px] text-[#57715B]/60 font-medium">
                          {percent.toFixed(1)}%
                        </span>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </GlassCard>
      </div>
    </div>
  );
}

