23	export function AnalyticsDashboard({ notas }: AnalyticsDashboardProps) {
24	  const isMobile = useIsMobile();
25	  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set());
26	
27	  const toggleCategory = (name: string): void => {
28	    setExpandedCategories(prev => {
29	      const next = new Set(prev);
30	      if (next.has(name)) {
31	        next.delete(name);
32	      } else {
33	        next.add(name);
34	      }
35	      return next;
36	    });
37	  };
38	
39	  const metrics = useMemo(() => {
40	    const totalNotas = notas.length;
41	    const totalValor = notas.reduce(
42	      (acc, curr) => acc + (parseFloat(curr.valor_total || '0') || 0),
43	      0,
44	    );
45	    const averageValor = totalNotas > 0 ? totalValor / totalNotas : 0;
46	
47	    const byMonthMap = new Map<string, number>();
48	    notas.forEach((nota) => {
49	      const date = new Date(nota.data_nota || nota.created_at);
