export function AnalyticsDashboard({ notas }: AnalyticsDashboardProps) {
  const isMobile = useIsMobile();
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set());

  const toggleCategory = (name: string): void => {
    setExpandedCategories(prev => {
      const next = new Set(prev);
      if (next.has(name)) {
        next.delete(name);
      } else {
        next.add(name);
      }
      return next;
    });
  };

  const metrics = useMemo(() => {
    const totalNotas = notas.length;
    const totalValor = notas.reduce(
      (acc, curr) => acc + (parseFloat(curr.valor_total || '0') || 0),
      0,
    );
    const averageValor = totalNotas > 0 ? totalValor / totalNotas : 0;

    const byMonthMap = new Map<string, number>();
    notas.forEach((nota) => {
      const date = new Date(nota.data_nota || nota.created_at);
      const key = String(date.getFullYear()) + '-' + String(date.getMonth() + 1).padStart(2, '0');
      const prev = byMonthMap.get(key) || 0;
      byMonthMap.set(key, prev + (parseFloat(nota.valor_total || '0') || 0));
    });

    const byMonth = Array.from(byMonthMap.entries())
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => a.name.localeCompare(b.name));

    const bySupplierMap = new Map<string, { display: string; value: number }>();
    notas.forEach((nota) => {
      const raw = (nota.fornecedor || 'Desconhecido').trim();
      const key = raw.toLowerCase();
      const prev = bySupplierMap.get(key);
      if (prev) {
        prev.value += parseFloat(nota.valor_total || '0') || 0;
      } else {
        bySupplierMap.set(key, { display: raw, value: parseFloat(nota.valor_total || '0') || 0 });
      }
    });

    const topSuppliers = Array.from(bySupplierMap.values())
      .map(({ display, value }) => ({ name: display, value }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 5);

    const byProductMap = new Map<string, number>(); // For uniqueProductsCount
    const byCategoryMap = new Map<string, number>(); // For PieChart data

    type ProductDetail = {
      nome_produto: string;
      valor: number;
      qtd: number;
      fornecedores: Set<string>;
    };
    const byCategoryProductsMap = new Map<string, Map<string, ProductDetail>>();

    notas.forEach((nota) => {
      const itens = nota.itens_nota_fiscal || [];
      itens.forEach((item: any) => {
        const subtotal = parseFloat(item.subtotal || '0');
        const quantidade = parseFloat(item.quantidade || '0');
        const prodName = item.nome_produto || 'Outros';
        const catName = normalizeCategoria(item.categoria); // Using normalizeCategoria

        // For unique products count
        byProductMap.set(
          prodName,
          (byProductMap.get(prodName) || 0) + subtotal,
        );

        // For category pie chart
        byCategoryMap.set(
          catName,
          (byCategoryMap.get(catName) || 0) + subtotal,
        );

        // For expandable category products list
        if (!byCategoryProductsMap.has(catName)) {
          byCategoryProductsMap.set(catName, new Map<string, ProductDetail>());
        }
        const productsInCat = byCategoryProductsMap.get(catName)!;

        if (!productsInCat.has(prodName)) {
          productsInCat.set(prodName, {
            nome_produto: prodName,
            valor: 0,
            qtd: 0,
            fornecedores: new Set<string>(),
          });
        }
        const product = productsInCat.get(prodName)!;
        product.valor += subtotal;
        product.qtd += quantidade;
        if (nota.fornecedor) {
          product.fornecedores.add(nota.fornecedor);
        }
      });
    });

    const topProducts = Array.from(byProductMap.entries())
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value)
      .slice(0, 5);

    const uniqueProductsCount = byProductMap.size;

    const byCategory = Array.from(byCategoryMap.entries())
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    // Convert byCategoryProductsMap to the desired Record format and sort products

  // Convert byCategoryProductsMap to the desired Record format and sort products
  const byCategoryProducts: Record<string, Array<{ nome_produto: string; valor: number; qtd: number; fornecedores: string[] }>> = {};
  byCategoryProductsMap.forEach((productsMap, categoryName) => {
    const productsArray = Array.from(productsMap.values()).map(p => ({
      ...p,
      fornecedores: Array.from(p.fornecedores), // Convert Set to Array
    }));
    productsArray.sort((a, b) => b.valor - a.valor); // Sort by value descending
    byCategoryProducts[categoryName] = productsArray;
  });

  return {
    totalNotas,
    totalValor,
    averageValor,
    byMonth,
    topSuppliers,
    topProducts,
    byCategory,
    uniqueProductsCount,
    byCategoryProducts, // Add new metric
  };
}, [notas]);

const currencyFormatter = (value: number) =>
  new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL',
  }).format(value);

const COLORS = [
  '#57715B',
  '#C5A065',
  '#8FA893',
  '#D4B886',
  '#3A4D3D',
  '#8F7348',
  '#2D362E',
];

return (
  <div className="space-y-6 animate-in fade-in duration-500">
    <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
      <GlassCard
        variant="premium"
        className="p-6 flex items-center justify-between group hover:scale-[1.02] transition-transform duration-300"
      >
        <div>
          <p className="text-[10px] font-bold text-[#C5A065] uppercase tracking-wider">
            Total Gasto
          </p>
          <h3 className="text-2xl font-bold text-[#2D362E] dark:text-[#E6DCCF] mt-1 tabular-nums">
            {currencyFormatter(metrics.totalValor)}
          </h3>
        </div>
        <div className="h-12 w-12 bg-[#C5A065]/10 rounded-2xl flex items-center justify-center group-hover:bg-[#C5A065]/20 transition-colors">
          <DollarSign className="h-6 w-6 text-[#C5A065]" />
        </div>
      </GlassCard>

