import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { AnalyticsDashboard } from './AnalyticsDashboard';

vi.mock('recharts', () => ({
    ResponsiveContainer: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
    BarChart: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
    PieChart: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
    Bar: () => null,
    Pie: () => null,
    Cell: () => null,
    XAxis: () => null,
    YAxis: () => null,
    CartesianGrid: () => null,
    Tooltip: () => null,
}));

vi.mock('@/shared/hooks/use-mobile', () => ({
    useIsMobile: () => false,
}));

vi.mock('@/shared/ui/glass-card', () => ({
    GlassCard: ({ children, className }: { children: React.ReactNode; className?: string }) => (
        <div className={className}>{children}</div>
    ),
}));

vi.mock('lucide-react', async (importOriginal) => {
    const actual = await importOriginal<typeof import('lucide-react')>();
    return {
        ...actual,
        ChevronDown: vi.fn(() => <svg data-testid="chevron-down" />),
    };
});

vi.mock('@/features/notas-fiscais/lib/categorias', () => ({
    normalizeCategoria: (raw: string | null | undefined): string => {
        if (!raw) return 'Outros';
        const key = raw.trim().toLowerCase();
        if (key === 'alimenticio' || key === 'alimento' || key === 'alimentos') return 'Alimenticio';
        if (key === 'embalagem' || key === 'embalagens') return 'Embalagens';
        if (key === 'operacional') return 'Outros';
        return 'Outros';
    },
}));

const calcMetrics = (notas: Array<{ valor_total: string; fornecedor?: string; data_nota: string; itens_nota_fiscal: unknown[] }>) => {
    const totalNotas = notas.length;
    const totalValor = notas.reduce(
        (acc, curr) => acc + (parseFloat(curr.valor_total) || 0),
        0,
    );
    const averageValor = totalNotas > 0 ? totalValor / totalNotas : 0;

    const bySupplierMap = new Map<string, number>();
    notas.forEach((nota) => {
        const name = nota.fornecedor || 'Desconhecido';
        bySupplierMap.set(name, (bySupplierMap.get(name) || 0) + (parseFloat(nota.valor_total) || 0));
    });

    const topSuppliers = Array.from(bySupplierMap.entries())
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value)
        .slice(0, 5);

    return { totalNotas, totalValor, averageValor, topSuppliers };
};

describe('AnalyticsDashboard -- metrics calculation', () => {
    const sampleNotas = [
        { valor_total: '1000', fornecedor: 'Fornecedor A', data_nota: '2025-01-15', itens_nota_fiscal: [] },
        { valor_total: '2000', fornecedor: 'Fornecedor B', data_nota: '2025-01-20', itens_nota_fiscal: [] },
        { valor_total: '500', fornecedor: 'Fornecedor A', data_nota: '2025-02-10', itens_nota_fiscal: [] },
    ];

    it('calculates totalNotas correctly', () => {
        const { totalNotas } = calcMetrics(sampleNotas);
        expect(totalNotas).toBe(3);
    });

    it('calculates totalValor correctly', () => {
        const { totalValor } = calcMetrics(sampleNotas);
        expect(totalValor).toBeCloseTo(3500, 0);
    });

    it('calculates averageValor correctly', () => {
        const { averageValor } = calcMetrics(sampleNotas);
        expect(averageValor).toBeCloseTo(3500 / 3, 0);
    });

    it('returns 0 average for empty notas', () => {
        const { averageValor } = calcMetrics([]);
        expect(averageValor).toBe(0);
    });

    it('groups suppliers and sorts by value', () => {
        const { topSuppliers } = calcMetrics(sampleNotas);
        expect(topSuppliers[0].name).toBe('Fornecedor B');
        expect(topSuppliers[1].name).toBe('Fornecedor A');
    });

    it('uses "Desconhecido" when fornecedor is missing', () => {
        const notasNoFornecedor = [{ valor_total: '1000', data_nota: '2025-01-01', itens_nota_fiscal: [] }];
        const { topSuppliers } = calcMetrics(notasNoFornecedor);
        expect(topSuppliers[0].name).toBe('Desconhecido');
    });
});

describe('AnalyticsDashboard -- smoke render', () => {
    it('renders without crashing with empty data', () => {
        render(<AnalyticsDashboard notas={[]} />);
        expect(document.body).toBeTruthy();
    });

    it('shows "Total Gasto" label', () => {
        render(<AnalyticsDashboard notas={[]} />);
        expect(screen.getByText('Total Gasto')).toBeInTheDocument();
    });

    it('shows "Notas Processadas" label', () => {
        render(<AnalyticsDashboard notas={[]} />);
        expect(screen.getByText('Notas Processadas')).toBeInTheDocument();
    });

    it('shows "Evolução Mensal" chart title', () => {
        render(<AnalyticsDashboard notas={[]} />);
        expect(screen.getByText('Evolução Mensal')).toBeInTheDocument();
    });
});

describe('AnalyticsDashboard -- categoria expansivel', () => {
    const notasComItens = [
        {
            valor_total: '500',
            fornecedor: 'Fornecedor Teste',
            data_nota: '2025-03-01',
            itens_nota_fiscal: [
                { nome_produto: 'Farinha de Amendoas', categoria: 'alimenticio', subtotal: '200', quantidade: '5' },
                { nome_produto: 'Caixa de Papel', categoria: 'embalagem', subtotal: '50', quantidade: '10' },
            ],
        },
        {
            valor_total: '300',
            fornecedor: 'Fornecedor B',
            data_nota: '2025-03-02',
            itens_nota_fiscal: [
                { nome_produto: 'Produto Operacional', categoria: 'operacional', subtotal: '100', quantidade: '2' },
                { nome_produto: 'Mel Organico', categoria: 'alimento', subtotal: '200', quantidade: '3' },
            ],
        },
    ];

    it('renders categoria Alimenticio na legenda', () => {
        render(<AnalyticsDashboard notas={notasComItens} />);
        expect(screen.getByText('Alimenticio')).toBeInTheDocument();
    });

    it('renders categoria Outros normalizada de operacional', () => {
        render(<AnalyticsDashboard notas={notasComItens} />);
        expect(screen.getByText('Outros')).toBeInTheDocument();
    });

    it('expande categoria ao clicar e mostra produto', () => {
        render(<AnalyticsDashboard notas={notasComItens} />);
        const btn = screen.getByRole('button', { name: /Alimenticio/i });
        expect(btn).toHaveAttribute('aria-expanded', 'false');
        fireEvent.click(btn);
        expect(btn).toHaveAttribute('aria-expanded', 'true');
        expect(screen.getByText('Farinha de Amendoas')).toBeInTheDocument();
    });

    it('fecha categoria ao clicar de novo', () => {
        render(<AnalyticsDashboard notas={notasComItens} />);
        const btn = screen.getByRole('button', { name: /Alimenticio/i });
        fireEvent.click(btn);
        expect(screen.getByText('Farinha de Amendoas')).toBeInTheDocument();
        fireEvent.click(btn);
        expect(screen.queryByText('Farinha de Amendoas')).not.toBeInTheDocument();
    });
});
